<?php

use App\Models\{Company, Site};
use App\Support\CurrentCompany;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
use Livewire\Attributes\Title;
use Livewire\Component;
use Livewire\WithFileUploads;

new #[Title('Company')] class extends Component {
    use WithFileUploads;
    public ?Company $company=null; public string $companyTab='details'; public string $name=''; public ?string $trading_name=null; public string $code=''; public ?string $address=null; public ?int $home_site_id=null; public ?string $email=null; public ?string $phone=null; public string $document_prefix=''; public bool $is_active=true; public ?string $registration_number=null; public ?string $vat_number=null; public ?string $brand_primary_color=null; public $logo=null;
    public string $site_name=''; public string $site_address_line_1=''; public ?string $site_address_line_2=null; public ?string $site_town=null; public ?string $site_county=null; public string $site_postcode='';
    public function mount(CurrentCompany $currentCompany, ?Company $company=null):void { if ($company && ! Auth::user()->hasRole('Super-Admin')) abort_unless($company->id === $currentCompany->id(Auth::user()), 404); $this->company=$company; if(!$company)return; foreach(['name','trading_name','code','address','home_site_id','email','phone','document_prefix','registration_number','vat_number','brand_primary_color','is_active'] as $field)$this->{$field}=$company->{$field}; }
    public function save():mixed { Gate::authorize($this->company?'admin.company.update':'admin.company.create'); $data=$this->validate(['name'=>['required','string','max:255'],'trading_name'=>['nullable','string','max:255'],'code'=>['required','string','max:20',Rule::unique('companies')->ignore($this->company?->id)],'address'=>['nullable','string','max:2000'],'home_site_id'=>['nullable',Rule::exists('sites','id')->where('company_id',$this->company?->id)],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:100'],'document_prefix'=>['required','string','max:20'],'registration_number'=>['nullable','string','max:100'],'vat_number'=>['nullable','string','max:100'],'brand_primary_color'=>['nullable','regex:/^#[0-9A-Fa-f]{6}$/'],'logo'=>['nullable','image','max:2048'],'is_active'=>['boolean']]); unset($data['logo']); if($this->logo)$data['logo_path']=$this->logo->store('company-logos','public'); $this->company?$this->company->update($data):$this->company=Company::create($data); Flux::toast(text:'Company saved',variant:'success'); return $this->redirectRoute('settings.companies.index',navigate:true); }
    public function createSite():void { Gate::authorize('crm.site.create'); abort_unless($this->company,404); $data=$this->validate(['site_name'=>['required','max:255'],'site_address_line_1'=>['required','max:255'],'site_address_line_2'=>['nullable','max:255'],'site_town'=>['nullable','max:255'],'site_county'=>['nullable','max:255'],'site_postcode'=>['required','max:20']]); $normalised=Str::upper(preg_replace('/[^A-Z0-9]/i','',implode('|',array_values($data)))); $site=Site::create(['company_id'=>$this->company->id,'name'=>$data['site_name'],'address_line_1'=>$data['site_address_line_1'],'address_line_2'=>$data['site_address_line_2'],'town'=>$data['site_town'],'county'=>$data['site_county'],'postcode'=>Str::upper($data['site_postcode']),'address_code'=>hash('sha256',$normalised)]); $this->home_site_id=$site->id; $this->reset(['site_name','site_address_line_1','site_address_line_2','site_town','site_county','site_postcode']); Flux::modal('create-company-site')->close(); Flux::toast(text:'Site created and selected',variant:'success'); }
    public function with():array{return['sites'=>$this->company?Site::where('company_id',$this->company->id)->orderBy('name')->get():collect()];}
};
?>
<section class="w-full">@include('partials.settings-heading',['section'=>$company?'Update company':'Create company'])<x-pages::settings.layout contentclass="mt-5 w-full max-w-4xl"><div class="mb-5 flex items-center justify-between"><flux:heading size="lg">{{ $company?'Update company':'Create company' }}</flux:heading><flux:button variant="ghost" :href="route('settings.companies.index')">Back</flux:button></div><div class="mb-5 flex gap-2 border-b pb-3"><flux:button type="button" :variant="$companyTab==='details'?'primary':'ghost'" wire:click="$set('companyTab','details')">Company</flux:button><flux:button type="button" :variant="$companyTab==='address'?'primary':'ghost'" wire:click="$set('companyTab','address')">Address</flux:button><flux:button type="button" :variant="$companyTab==='branding'?'primary':'ghost'" wire:click="$set('companyTab','branding')">Branding</flux:button></div><form wire:submit="save" class="space-y-5">@if($companyTab==='details')<div class="grid gap-5 md:grid-cols-2"><flux:input wire:model="name" label="Legal company name" required/><flux:input wire:model="trading_name" label="Trading name"/><flux:input wire:model="code" label="Code" required/><flux:switch wire:model="is_active" label="Active tenant"/><flux:input wire:model="email" label="Email"/><flux:input wire:model="phone" label="Phone"/></div>@elseif($companyTab==='address')<div class="space-y-4">@if($company)<div class="flex items-end gap-2"><div class="flex-1"><flux:select wire:model="home_site_id" variant="combobox" clearable label="Home depot and postal address" placeholder="Search sites or postcodes..."><flux:select.option value="">Not set</flux:select.option>@foreach($sites as $site)<flux:select.option :value="$site->id">{{ $site->name }} — {{ $site->formattedAddress() }}</flux:select.option>@endforeach</flux:select></div><flux:modal.trigger name="create-company-site"><flux:button type="button" icon="plus">New site</flux:button></flux:modal.trigger></div><flux:text>Addresses are reusable Site records and are not duplicated on the tenant.</flux:text>@else<flux:callout>Save the company first, then return to add its address.</flux:callout>@endif</div>@else<div class="grid gap-5 md:grid-cols-2"><flux:input wire:model="document_prefix" label="Document prefix" required/><flux:input wire:model="brand_primary_color" type="color" label="Brand colour"/><flux:input wire:model="registration_number" label="Company registration"/><flux:input wire:model="vat_number" label="VAT number"/><flux:input wire:model="logo" type="file" accept="image/png,image/jpeg,image/webp" label="Logo"/>@if($company?->logo_path)<img src="{{ Storage::url($company->logo_path) }}" alt="Current logo" class="max-h-20 max-w-52 object-contain">@endif</div>@endif<div class="flex justify-end gap-3 border-t pt-4"><flux:button variant="ghost" :href="route('settings.companies.index')">Cancel</flux:button><flux:button type="submit" variant="primary">Save company</flux:button></div></form><flux:modal name="create-company-site" class="min-w-[34rem]"><div class="space-y-4"><flux:heading size="lg">Create and select site</flux:heading><flux:input wire:model="site_name" label="Site name"/><flux:input wire:model="site_address_line_1" label="Address line 1"/><flux:input wire:model="site_address_line_2" label="Address line 2"/><div class="grid gap-3 sm:grid-cols-3"><flux:input wire:model="site_town" label="Town"/><flux:input wire:model="site_county" label="County"/><flux:input wire:model="site_postcode" label="Postcode"/></div><div class="flex justify-end gap-2"><flux:modal.close><flux:button variant="ghost">Cancel</flux:button></flux:modal.close><flux:button type="button" variant="primary" wire:click="createSite">Create and select</flux:button></div></div></flux:modal></x-pages::settings.layout></section>
